// Sample 1: Basic integer declaration
int counter = 10;
print(counter);

// Sample 2: Float numbers
float pi = 3.1415;
float radius = 2.5;
float area = pi * radius * radius;
print(area);

// Sample 3: Precedence verification
int a = 10;
int b = 5;
int result = a + b * 2;
print(result);

// Sample 4: Parenthesized expression
int a = 10;
int b = 5;
int overrideResult = (a + b) * 2;
print(overrideResult);

// Sample 5: Multi-step calculation
int base = 100;
int step = 25;
base = base + step;
int total = base * 2;
print(total);

// Sample 6: Missing semicolon on line 2
int a = 10
int b = 20;
print(b);

// Sample 7: Missing closing parenthesis
int a = 10;
int result = (a + 5 * 2;
print(result);

// Sample 8: Illegal symbols @ and $
int score = 100 @ 2;
float cost = $50.0;

// Sample 9: Malformed float literal 12.34.56
float val = 12.34.56;
print(val);

// Sample 10: Undeclared variable usage
speed = 60;
int time = 2;
int distance = speed * time;
print(distance);

// Sample 11: Re-declaration of 'x'
int x = 10;
int y = 20;
int x = 30;
print(x);

// Sample 12: Static division by zero
int a = 50;
int b = a / 0;
print(b);

// Sample 13: Complete compiler showcase
int x = 10;
int y = 20;
float factor = 1.5;
int sum = (x + y) * 2;
print(sum);
